def clamp(x, lo, hi):
    # If lo > hi, swap them
    if lo is not None and hi is not None and lo > hi:
        lo, hi = hi, lo

    # If lo is None, no lower bound
    if lo is None:
        lo = -float('inf')

    # If hi is None, no upper bound
    if hi is None:
        hi = float('inf')

    # Clamp the value
    if x < lo:
        return lo
    elif x > hi:
        return hi
    else:
        return x

